-- Divine Circle: precio especial por un tiempo, descuento de una vez y abonos. Una sentencia por linea. Pegar todo y Run, despues de setup.sql, seguridad.sql y fijos.sql.
alter table public.offerings add column if not exists promo_price integer check (promo_price >= 0);
alter table public.offerings add column if not exists promo_until date;
alter table public.orders add column if not exists discount integer check (discount >= 0);
alter table public.orders add column if not exists paid_amount integer check (paid_amount >= 0);
create or replace function public.place_web_order( p_client text, p_phone text, p_date date, p_lines jsonb, p_note text default null ) returns uuid language plpgsql security definer set search_path = public as $$ declare v_items jsonb := '[]'::jsonb; v_line jsonb; v_off public.offerings; v_qty integer; v_id uuid; begin if coalesce(trim(p_client), '') = '' then raise exception 'falta el nombre'; end if; if p_date < current_date then raise exception 'fecha en el pasado'; end if; if jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) = 0 then raise exception 'pedido vacio'; end if; for v_line in select * from jsonb_array_elements(p_lines) loop v_qty := (v_line ->> 'qty')::integer; if v_qty is null or v_qty < 1 or v_qty > 50 then raise exception 'cantidad invalida'; end if; select * into v_off from public.offerings where code = upper(v_line ->> 'code') and active and public; if not found then raise exception 'codigo no disponible: %', v_line ->> 'code'; end if; v_items := v_items || jsonb_build_object( 'offeringId', v_off.id, 'code', v_off.code, 'name', v_off.name, 'qty', v_qty, 'unitPrice', case when v_off.promo_price is not null and v_off.promo_until >= p_date then v_off.promo_price else v_off.price end); end loop; insert into public.orders (client, phone, date, items, note, source) values (left(trim(p_client), 120), left(p_phone, 40), p_date, v_items, left(p_note, 500), 'web') returning id into v_id; return v_id; end; $$;
